type GenerateThreadTitleArgs = Parameters<NonNullable<RunRegistryEntry['generateThreadTitle']>>[0];
type AnyAgent = Agent<any, any, any, any>;

export interface DurableFinishSideEffectsOptions {
  runId: string;
  initData: DurableAgenticWorkflowInput;
  messageListState: SerializedMessageListState;
  mastra?: Mastra;
  requestContext?: RequestContext;
  tracingContext?: TracingContext;
  logger?: IMastraLogger;
  outputResult?: OutputResult;
  /**
   * The current response message id. Signals, goals and isTaskComplete rotate it during
   * the run, so `initData.messageId` can name an earlier reply. Defaults to that id.
   */
  messageId?: string;
}

export interface DurableFinishSideEffectsResult {
  messageListState: SerializedMessageListState;
  outputText: string;
  /**
   * True when processOutputResult changed `outputText`, including emptying it. Only then should
   * callers apply `outputText` to the run's last step: otherwise the step's own text stands,
   * e.g. the narration of a final tool step whose last message has no text.
   */
  outputTextChanged: boolean;
  titleGeneration?: Promise<void>;
  /**
   * Set when this stream() run should emit a `data-thread-title` chunk (`generateTitle.emitEvent`).
   * Resolves with the saved title, or undefined when none was generated. Callers await it
   * before FINISH so the chunk lands first, matching the in-process loop.
   */
  titleForStream?: Promise<string | undefined>;
  /** Chunks from the `structuredOutput.model` structuring pass, to publish before FINISH. */
  structuredOutputChunks?: ChunkType[];
  /**
   * Chunks output processors wrote with `writer.custom()` in processOutputResult. Publish them
   * marked output-processed, after `structuredOutputChunks` and before the tripwire or FINISH,
   * matching the in-process loop.
   */
  outputResultChunks?: ChunkType[];
  /** Set when an output processor aborted in processOutputResult; nothing was persisted. */
  tripwire?: {
    reason: string;
    processorId?: string;
    retry?: boolean;
    metadata?: unknown;
  };
}

function restoreRequestContext(
  entries: Record<string, unknown> | undefined,
  fallback: RequestContext | undefined,
): RequestContext {
  if (!entries) return fallback ?? new RequestContext();

  const restored = new RequestContext<unknown>(fallback?.entries());
  // The snapshot's token and signed-in user belong to whoever started the run;
  // the live ones in `fallback` are kept.
  for (const [key, value] of Object.entries(withoutLiveRequestKeys(entries))) restored.set(key, value);
  restoreRunAgentScopes(restored);
  return restored;
}

function resolveOutputText(messageList: MessageList): string {
  const responseMessages = messageList.get.response.db();
  const hasCompletionCheckMessages = responseMessages.some(message => message.content?.metadata?.completionResult);
  if (hasCompletionCheckMessages) {
    const lastRealMessage = responseMessages.findLast(message => !message.content?.metadata?.completionResult);
    const converted = lastRealMessage ? convertMessages([lastRealMessage]).to('AIV4.Core') : [];
    const lastConverted = converted.at(-1);
    return lastConverted ? coreContentToString(lastConverted.content) : '';
  }

  const converted = messageList.get.response.aiV4.core();
  const lastResponseMessage = converted.at(-1);
  return lastResponseMessage ? coreContentToString(lastResponseMessage.content) : '';
}

/**
 * Run the side effects that happen after the durable agentic loop reaches its
 * terminal state. Every durable engine calls this before emitting its finish
 * event so remote workers provide the same behavior as the built-in engine.
 *
 * The returned state is the SAME MessageList that output processors mutated
 * and memory persistence flushed. Callers must use it in their final output;
 * rebuilding from the pre-processor state would discard redactions and other
 * processOutputResult changes.
 */
export async function runDurableFinishSideEffects({
  runId,
  initData,
  messageListState,
  mastra,
  requestContext,
  tracingContext,
  logger,
  outputResult,
  messageId = initData.messageId,
}: DurableFinishSideEffectsOptions): Promise<DurableFinishSideEffectsResult> {
  const effectiveLogger = logger ?? mastra?.getLogger?.() ?? noopLogger;
  const durableState = initData.state;

  // A connect() worker has a separate process-local registry. Rebuild the
  // agent's runtime dependencies when the terminal step cannot see the
  // processor pipeline or the memory save queue prepared by stream().
  let registryEntry = getRunRegistryEntry(runId, mastra as Mastra | undefined);
  // resolveRuntimeDependencies only writes its rebuild back into the registry when it
  // rehydrated from Mastra, so an already-hydrated entry that was seeded without a save
  // queue would still be missing one afterwards. Keep what it returns and prefer that.
  let rebuiltSaveQueueManager: RunRegistryEntry['saveQueueManager'] | undefined;
  let rebuiltMemory: MastraMemory | undefined;
  const needsProcessorRebuild = registryEntry?.outputProcessors === undefined;
  const needsMemoryRebuild = !!durableState?.threadId && !registryEntry?.saveQueueManager;
  if ((needsProcessorRebuild || needsMemoryRebuild) && mastra) {
    try {
      const resolved = await resolveRuntimeDependencies({
        mastra,
        runId,
        agentId: initData.agentId,
        // initData read back from a snapshot may keep saved messages as refs.
        input: { ...initData, messageListState },
        logger: effectiveLogger,
      });
      rebuiltSaveQueueManager = resolved.saveQueueManager;
      rebuiltMemory = resolved.memory;
      registryEntry = getRunRegistryEntry(runId, mastra as Mastra | undefined);
    } catch (error) {
      effectiveLogger.error('[DurableAgent] Failed to rebuild finish-time dependencies', {
        agentId: initData.agentId,
        runId,
        error,
      });
    }
  }

  const effectiveRequestContext = restoreRequestContext(initData.requestContextEntries, requestContext);
  // Snapshots drop MastraMemory (it holds a live instance), but memory processors read
  // memoryConfig (e.g. readOnly) from it. Restore it from durable state when it's missing.
  if (!effectiveRequestContext.has('MastraMemory') && durableState?.threadId) {
    effectiveRequestContext.set('MastraMemory', {
      thread: { id: durableState.threadId },
      resourceId: durableState.resourceId,
      memoryConfig: durableState.memoryConfig,
    });
  }
  // Deserialize into the run's existing MessageList when there is one. MastraModelOutput
  // holds that instance and reads it during final processing, so swapping in a new one
  // would leave the stream reporting pre-processor messages.
  const messageList = (
    registryEntry?.messageList ??
    new MessageList({
      threadId: durableState?.threadId,
      resourceId: durableState?.resourceId,
    })
  ).deserialize(messageListState);
  if (registryEntry) {
    registryEntry.messageList = messageList;
  }
  // A background result that landed after the last background check is still a placeholder here.
  await foldBackgroundResults(registryEntry, messageList);

  // The caller-side MastraModelOutput only sees the finish event after this step has
  // persisted messages, and remote/recovered runs have no caller at all. Attach the
  // validated object here so the saved assistant message matches plain Agent output.
  // Like Agent, this runs before output processors so processors that persist the turn
  // themselves (observational memory) save the object too.
  // This mirrors createObjectStreamTransformer's finalize: truncated finishes never validate,
  // and failures follow errorStrategy. Prefer the live config (keeps Zod refinements/transforms
  // and non-JSON fallback values). Remote and recovered runs only have the persisted config,
  // which is what cross-process observers use too.
  const structuredOutput = initData.options?.structuredOutput;
  const structuredOutputText = resolveOutputText(messageList);
  const liveStructuredOutput = registryEntry?.structuredOutput;
  const structuredOutputSchema =
    liveStructuredOutput?.schema ??
    (structuredOutput?.schema
      ? toLiveStructuredOutputSchema(structuredOutput.schema, structuredOutput.nullToUndefined)
      : undefined);
  let structuredOutputChunks: ChunkType[] | undefined;
  // The structuring model reads tool calls and results too, so a tool-only answer still qualifies.
  const structuringParts = structuredOutput?.hasStructuringModel ? responseStreamParts(messageList) : undefined;
  if (structuredOutputSchema && (structuredOutputText.trim() || structuringParts?.length)) {
    const finishReason = outputResult?.finishReason;
    const truncated = finishReason === 'length' || finishReason === 'content-filter';
    const errorStrategy = liveStructuredOutput ? liveStructuredOutput.errorStrategy : structuredOutput?.errorStrategy;
    const fallbackValue = liveStructuredOutput ? liveStructuredOutput.fallbackValue : structuredOutput?.fallbackValue;
    let value: unknown;
    if (structuredOutput?.hasStructuringModel) {
      // Like Agent's StructuredOutputProcessor: the main model answered in text, so a
      // separate structuring model turns that answer into the object.
      const structuringModel = liveStructuredOutput?.model ?? structuredOutput.structuringModelConfig?.originalConfig;
      // Never structure partial text from an aborted or failed turn.
      const failed = finishReason === 'abort' || finishReason === 'error';
      if (structuringModel && !truncated && !failed) {
        structuredOutputChunks = await runStructuringPass({
          options: {
            ...(liveStructuredOutput ?? {}),
            schema: liveStructuredOutput?.schema ?? toStandardSchema(structuredOutput.schema!),
            model: structuringModel as any,
            instructions: liveStructuredOutput?.instructions ?? structuredOutput.instructions,
            jsonPromptInjection: liveStructuredOutput?.jsonPromptInjection ?? structuredOutput.jsonPromptInjection,
            errorStrategy,
            fallbackValue,
          } as StructuredOutputOptions<any>,
          mastra,
          agentId: initData.agentId,
          messageList,
          streamParts: structuringParts!,
          requestContext: effectiveRequestContext,
          logger: effectiveLogger,
        });
        const objectChunk = structuredOutputChunks.findLast(chunk => chunk.type === 'object-result');
        value = objectChunk?.type === 'object-result' ? objectChunk.object : undefined;
      } else if (!structuringModel) {
        effectiveLogger.warn('[DurableAgent] structuredOutput.model is not available on this worker', { runId });
      }
    } else {
      const result = truncated
        ? undefined
        : await createOutputHandler({ schema: structuredOutputSchema }).validateAndTransformFinal(structuredOutputText);
      value = result?.success ? result.value : errorStrategy === 'fallback' ? fallbackValue : undefined;
    }
    const lastAssistantMessage = messageList.get.response
      .db()
      .findLast(message => message.role === 'assistant' && !message.content?.metadata?.completionResult);
    if (value !== undefined && lastAssistantMessage) {
      lastAssistantMessage.content.metadata = {
        ...lastAssistantMessage.content.metadata,
        structuredOutput: value,
      };
    }
  }

  // Output processors persist messages too (MessageHistory saves the response
  // in processOutputResult), so a superseded execution must stop here, before
  // either memory write path, and never reach the finish event (#23734). This
  // check uses the live `requestContext`: the snapshot entries never carry the
  // execution id.
  const assertOwned = () => assertExecutionOwned({ runId, agentId: initData.agentId, requestContext, mastra });
  await assertOwned();

  // A signal drained on the last allowed step rotates the id, then the loop stops before any
  // reply uses it. Attach data to the final reply instead of saving it as its own message.
  // Resolved before processors run so their own writes can't become the fallback.
  const responses = messageList.get.response.db();
  const replyMessageId = responses.some(message => message.id === messageId)
    ? messageId
    : (resolveOutputMessageSkippingCompletionChecks(messageList)?.id ?? messageId);

  // This step has no pubsub (remote engines call it too), so chunks are buffered for the
  // caller. Non-transient ones go into the MessageList now so the flush below saves them.
  const outputResultChunks: ChunkType[] = [];
  const outputResultWriter = {
    custom: async (
      data: { type: string; data?: unknown; transient?: boolean },
      writerOptions?: { messageId?: string },
    ) => {
      persistProcessorDataChunk(messageList, writerOptions?.messageId ?? replyMessageId, data);
      outputResultChunks.push(data as ChunkType);
    },
  };

  const outputTextBeforeProcessing = resolveOutputText(messageList);

  // Keep this MessageList for every later phase. ProcessorRunner applies
  // returned message arrays back onto it, including removals and replacements.
  if (registryEntry?.outputProcessors?.length) {
    try {
      let agent: AnyAgent | undefined = registryEntry.agent;
      if (!agent && mastra) {
        try {
          const registered = mastra.getAgentById(initData.agentId);
          agent = isDurableAgentLike(registered) && registered.agent !== registered ? registered.agent : registered;
        } catch {
          agent = undefined;
        }
      }

      const runner = new ProcessorRunner({
        inputProcessors: registryEntry.inputProcessors ?? [],
        outputProcessors: registryEntry.outputProcessors,
        errorProcessors: registryEntry.errorProcessors ?? [],
        logger: effectiveLogger,
        agentName: initData.agentName ?? initData.agentId,
        agent,
        processorStates: registryEntry.processorStates,
      });
      await runner.runOutputProcessors(
        messageList,
        createObservabilityContext(tracingContext),
        effectiveRequestContext,
        0,
        outputResultWriter,
        outputResult,
      );
    } catch (error) {
      if (error instanceof TripWire) {
        // Match Agent: a tripwire rejects the answer, so skip persistence and title generation,
        // and remove any response messages this run already saved.
        await undoSavedResponseMessages({
          memory: registryEntry?.memory ?? rebuiltMemory,
          threadId: durableState?.threadId,
          memoryConfig: durableState?.memoryConfig,
          messageList,
          saveQueueManager: registryEntry?.saveQueueManager ?? rebuiltSaveQueueManager,
          logger: effectiveLogger,
          runId,
        });
        const outputText = resolveOutputText(messageList);
        return {
          messageListState: messageList.serialize(),
          outputText,
          outputTextChanged: outputText !== outputTextBeforeProcessing,
          outputResultChunks,
          tripwire: {
            reason: error.message,
            processorId: error.processorId,
            retry: error.options?.retry,
            metadata: error.options?.metadata,
          },
        };
      }
      effectiveLogger.warn('[DurableAgent] Error running output processors', { runId, error });
      // Ordinary history can retry through the strict queue flush below. OM owns
      // its final write and skips that flush, so its failure must propagate here.
      if (durableState?.observationalMemory) throw error;
    }
  }

  // SaveQueueManager may reclassify flushed response messages as persisted
  // memory, so resolve the final response text before persistence runs.
  const outputText = resolveOutputText(messageList);
  const outputTextChanged = outputText !== outputTextBeforeProcessing;

  const saveQueueManager = registryEntry?.saveQueueManager ?? rebuiltSaveQueueManager;
  const memory = registryEntry?.memory ?? rebuiltMemory;
  const authorizeMemory =
    durableState?.threadId && durableState.resourceId
      ? (permission: Parameters<typeof authorizeDurableMemory>[1]['permission']) =>
          authorizeDurableMemory(getDurableMemoryAuthorizationChecks(registryEntry), {
            mastra,
            user: effectiveRequestContext.get('user'),
            threadId: durableState.threadId!,
            resourceId: durableState.resourceId!,
            agentId: initData.agentId,
            requestContext: effectiveRequestContext,
            permission,
            actor: initData.options?.actor,
          })
      : undefined;

  if (
    saveQueueManager &&
    memory &&
    durableState?.threadId &&
    durableState?.resourceId &&
    !durableState.observationalMemory &&
    !durableState.memoryConfig?.readOnly
  ) {
    await authorizeMemory!(MastraFGAPermissions.MEMORY_WRITE);
    if (!durableState.threadExists) await authorizeMemory!(MastraFGAPermissions.MEMORY_READ);
    try {
      if (!durableState.threadExists) {
        await memory.createThread?.({
          threadId: durableState.threadId,
          resourceId: durableState.resourceId,
          memoryConfig: durableState.memoryConfig,
        });
      }

      await saveQueueManager.flushMessages(messageList, durableState.threadId, durableState.memoryConfig, {
        beforePersist: assertOwned,
        throwOnError: true,
      });
    } catch (error) {
      if (isExecutionFenceError(error)) throw error;
      effectiveLogger.error('[DurableAgent] Error persisting messages', {
        runId,
        threadId: durableState.threadId,
        error,
      });
      throw error;
    }
  }

  let titleGeneration: Promise<void> | undefined;
  let titleForStream: Promise<string | undefined> | undefined;

  // Same exclusions as the persistence block above: an observational-memory run writes no
  // messages here, and titling it would create a thread row holding a title and nothing else.
  if (
    durableState?.threadId &&
    durableState?.resourceId &&
    !durableState.observationalMemory &&
    !durableState.memoryConfig?.readOnly
  ) {
    const titleArgs: GenerateThreadTitleArgs = {
      threadId: durableState.threadId,
      resourceId: durableState.resourceId,
      memoryConfig: durableState.memoryConfig,
      messageListState: messageList.serialize(),
      requestContext: effectiveRequestContext,
      tracingContext,
    };

    const generateThreadTitle = registryEntry?.generateThreadTitle;
    await authorizeMemory!(MastraFGAPermissions.MEMORY_READ);
    await authorizeMemory!(MastraFGAPermissions.MEMORY_WRITE);
    const savedTitle = (async (): Promise<string | undefined> => {
      if (generateThreadTitle) {
        return generateThreadTitle(titleArgs);
      } else if (mastra) {
        const agent = mastra.getAgentById(initData.agentId);
        const titleMemory = memory ?? (await agent.getMemory({ requestContext: effectiveRequestContext }));
        if (titleMemory) {
          return generateDurableThreadTitle({ agent, memory: titleMemory, ...titleArgs });
        }
      }
      return undefined;
    })().catch(error => {
      effectiveLogger.warn('[DurableAgent] Error generating thread title', { runId, error });
      return undefined;
    });

    if (registryEntry?.streamThreadTitle) titleForStream = savedTitle;

    // The user callback runs after the title is saved but never holds FINISH.
    const onTitleGenerated = registryEntry?.onTitleGenerated;
    titleGeneration = savedTitle
      .then(async title => {
        if (title && onTitleGenerated) await onTitleGenerated(title);
      })
      .catch(error => {
        effectiveLogger.error('[DurableAgent] Error in onTitleGenerated callback', { runId, error });
      });
  }

  return {
    messageListState: messageList.serialize(),
    outputText,
    outputTextChanged,
    titleGeneration,
    titleForStream,
    structuredOutputChunks,
    outputResultChunks,
  };
}

/**
 * What a total deadline saves: the steps that completed in time, plus the step in flight. A step cut off
 * mid-stream contributes the text it already streamed, which never reached the step processors. A step cut off
 * while its tools ran is kept whole, with the tool results that came back in time or during the deadline's grace
 * window and any call still running saved as aborted.
 */
export function deadlineMessageListState(
  entry: RunRegistryEntry,
  fallback: SerializedMessageListState,
): { messageListState: SerializedMessageListState; cutOffText?: string } {
  if (entry.streamedStepText) {
    return { messageListState: entry.completedStepsState ?? fallback, cutOffText: entry.streamedStepText.join('') };
  }
  const settled = entry.settledToolResults;
  if (settled?.length && entry.messageList) {
    // JSON round-trip: the live list keeps mutating, and its metadata can hold functions.
    const inFlight = new MessageList().deserialize(JSON.parse(JSON.stringify(entry.messageList.serialize())));
    for (const result of settled) {
      commitToolResult({
        messageList: inFlight,
        outcome: result.outcome,
        toolCallId: result.toolCallId,
        toolName: result.toolName,
        toolArgs: result.args,
        approval: result.approval,
        providerMetadata: result.providerMetadata,
      });
    }
    // A sibling call still running past the grace window is saved as aborted, so the results
    // that did come back are not dropped with it.
    const unsettled = inFlight.get.response
      .db()
      .flatMap(message => message.content.parts ?? [])
      .filter(part => part.type === 'tool-invocation' && !isTerminalToolInvocationState(part.toolInvocation.state));
    for (const part of unsettled) {
      if (part.type !== 'tool-invocation') continue;
      commitToolResult({
        messageList: inFlight,
        outcome: { kind: 'result', result: TOOL_ABORT_NOTICE },
        toolCallId: part.toolInvocation.toolCallId,
        toolName: part.toolInvocation.toolName,
        toolArgs: part.toolInvocation.args,
      });
    }
    return { messageListState: inFlight.serialize() };
  }
  return { messageListState: entry.completedStepsState ?? fallback };
}

/**
 * Give the output processors (and with them memory) their one pass when a total deadline ends a
 * durable run. The run never reaches its finish step, so this runs over what the deadline saves
 * (see `deadlineMessageListState`), as the default loop's deadline pass does.
 */
export async function runDurableDeadlineOutputPass({
  runId,
  initData,
  messageListState,
  cutOffText,
  entry,
  mastra,
  tracingContext,
  logger,
}: {
  runId: string;
  initData: Pick<
    DurableAgenticWorkflowInput,
    'runId' | 'agentId' | 'agentName' | 'messageId' | 'state' | 'options' | 'requestContextEntries'
  >;
  messageListState: SerializedMessageListState;
  cutOffText?: string;
  entry: RunRegistryEntry;
  mastra?: Mastra;
  /** The run's agent span, so the deadline pass shows in the run's trace as the finish pass does. */
  tracingContext?: TracingContext;
  logger: IMastraLogger;
}): Promise<void> {
  const durableState = initData.state;
  const requestContext = restoreRequestContext(initData.requestContextEntries, entry.requestContext);
  if (!requestContext.has('MastraMemory') && durableState?.threadId) {
    requestContext.set('MastraMemory', {
      thread: { id: durableState.threadId },
      resourceId: durableState.resourceId,
      memoryConfig: durableState.memoryConfig,
    });
  }
  const memoryContext = requestContext.get('MastraMemory') as
    | { thread?: { id?: string }; resourceId?: string; memoryConfig?: { readOnly?: boolean } }
    | undefined;
  // A read-only run writes nothing to memory, at the deadline either.
  if (durableState?.memoryConfig?.readOnly || memoryContext?.memoryConfig?.readOnly) return;

  // The output processors save the turn (MessageHistory) to the thread the run or its request context
  // names, so the caller needs write access to each first. A denial skips the whole save.
  const resourceId = durableState?.resourceId ?? memoryContext?.resourceId;
  if (entry.memory && resourceId) {
    const threadIds = new Set([durableState?.threadId, memoryContext?.thread?.id].filter(Boolean) as string[]);
    try {
      for (const threadId of threadIds) {
        // The run's cached grant covers only its own thread; a thread the request context points at is checked anew.
        const checks = threadId === durableState?.threadId ? getDurableMemoryAuthorizationChecks(entry) : new Map();
        await authorizeDurableMemory(checks, {
          mastra,
          user: requestContext.get('user'),
          threadId,
          resourceId,
          agentId: initData.agentId,
          requestContext,
          permission: MastraFGAPermissions.MEMORY_WRITE,
          actor: initData.options?.actor,
        });
      }
    } catch (authError) {
      logger.warn('[DurableAgent] Memory write denied at the total deadline, the turn is not saved', {
        runId,
        error: authError,
      });
      return;
    }
  }

  const messageList = new MessageList({
    threadId: durableState?.threadId,
    resourceId: durableState?.resourceId,
  }).deserialize(
    // A resumed run's persisted input keeps messages memory already stores as refs (a recovered run's
    // crash-time transcript is hydrated already). Defensive: refs only reach here when a resumed run's
    // deadline fires before its first step snapshot with no settled tool results, which no test drives.
    await hydrateMessageListState({ getInitData: () => initData, mastra, requestContext }, messageListState),
  );
  // Untargeted processor data lands on the reply, as at finish; resolved before the cut-off text is added.
  const replyMessageId = resolveOutputMessageSkippingCompletionChecks(messageList)?.id ?? initData.messageId;
  let inFlightMessageId: string | undefined;
  if (cutOffText?.trim()) {
    messageList.add({ role: 'assistant', content: [{ type: 'text', text: cutOffText }] }, 'response', {
      merge: false,
    });
    inFlightMessageId = messageList.get.response.db().at(-1)!.id;
  }

  if (entry.outputProcessors?.length) {
    const runner = new ProcessorRunner({
      inputProcessors: entry.inputProcessors ?? [],
      outputProcessors: entry.outputProcessors,
      errorProcessors: entry.errorProcessors ?? [],
      logger,
      agentName: initData.agentName ?? initData.agentId,
      agent: entry.agent,
      processorStates: entry.processorStates,
    });
    // Data parts a step processor writes for the cut-off text, whether it names that message or not, are
    // held until the message is written back: the write-back replaces it, and would drop parts merged into it.
    let heldDataChunks:
      | { data: { type: string; data?: unknown; transient?: boolean }; messageId?: string }[]
      | undefined;
    const writer = {
      custom: async (
        data: { type: string; data?: unknown; transient?: boolean },
        writerOptions?: { messageId?: string },
      ) => {
        if (heldDataChunks && (!writerOptions?.messageId || writerOptions.messageId === inFlightMessageId)) {
          heldDataChunks.push({ data, messageId: writerOptions?.messageId });
        } else {
          persistProcessorDataChunk(
            messageList,
            resolveProcessorWriterMessageId(messageList, replyMessageId, writerOptions?.messageId),
            data,
          );
        }
      },
    };
    if (inFlightMessageId) {
      heldDataChunks = [];
      // The cut-off text never reached the step processors (redaction, refusal handling...).
      // Run them over that message alone: the rest of the turn already went through them.
      try {
        const stepList = messageList.clone();
        stepList.removeByIds(
          stepList.get.all
            .db()
            .map(message => message.id)
            .filter(id => id !== inFlightMessageId),
        );
        await runner.runProcessOutputStep({
          steps: [],
          messages: stepList.get.all.db(),
          messageList: stepList,
          stepNumber: 0,
          finishReason: 'error',
          text: cutOffText,
          ...createObservabilityContext(tracingContext),
          requestContext,
          writer,
        });
        messageList.removeByIds([inFlightMessageId]);
        for (const message of stepList.get.all.db()) messageList.add(message, 'response', { merge: false });
      } catch (stepError) {
        // Fail closed: keep the completed steps rather than save unprocessed text. The result processors
        // then read the text of the completed steps only.
        messageList.removeByIds([inFlightMessageId]);
        logger.warn('[DurableAgent] Output step processors failed on the text cut off at the total deadline', {
          runId,
          error: stepError,
        });
      }
      for (const { data, messageId } of heldDataChunks) {
        // A part aimed at the cut-off message lands on it if it survived the write-back,
        // otherwise on the message an untargeted write would reach.
        const target =
          messageId && messageList.get.all.db().some(message => message.id === messageId)
            ? messageId
            : resolveProcessorWriterMessageId(messageList, replyMessageId);
        persistProcessorDataChunk(messageList, target, data);
      }
      heldDataChunks = undefined;
    }
    try {
      await runner.runOutputProcessors(
        messageList,
        createObservabilityContext(tracingContext),
        requestContext,
        0,
        writer,
        {
          text: resolveOutputText(messageList),
          usage: { inputTokens: undefined, outputTokens: undefined, totalTokens: undefined },
          finishReason: 'error',
          steps: [],
        },
      );
    } catch (processorError) {
      // A tripwire rejects the turn, as it does at finish: remove response messages already saved.
      if (processorError instanceof TripWire) {
        await undoSavedResponseMessages({
          memory: entry.memory,
          threadId: durableState?.threadId,
          memoryConfig: durableState?.memoryConfig,
          messageList,
          saveQueueManager: entry.saveQueueManager,
          logger,
          runId,
        });
        return;
      }
      logger.warn('[DurableAgent] Error running output processors at the total deadline', {
        runId,
        error: processorError,
      });
      if (durableState?.observationalMemory) return;
    }
  }

  if (
    !entry.saveQueueManager ||
    !entry.memory ||
    !durableState?.threadId ||
    !durableState.resourceId ||
    durableState.observationalMemory
  ) {
    return;
  }
  await entry.saveQueueManager.flushMessages(messageList, durableState.threadId, durableState.memoryConfig, {
    throwOnError: true,
  });
}

class StructuringPassError extends Error {
  constructor(message: string, cause?: unknown) {
    super(message, { cause });
    this.name = 'StructuringPassError';
  }
}

/**
 * Rebuild the chunks the structuring prompt reads (text, tool calls and results) from the
 * run's response messages; the durable finish step has no in-memory chunk history.
 */
function responseStreamParts(messageList: MessageList): ChunkType[] {
  const parts: ChunkType[] = [];
  for (const message of messageList.get.response.db()) {
    if (message.role !== 'assistant' || message.content?.metadata?.completionResult) continue;
    for (const part of message.content?.parts ?? []) {
      if (part.type === 'text') {
        parts.push({ type: 'text-delta', payload: { id: '', text: part.text } } as ChunkType);
      } else if (part.type === 'tool-invocation') {
        const { toolCallId, toolName, args } = part.toolInvocation;
        parts.push({ type: 'tool-call', payload: { toolCallId, toolName, args } } as ChunkType);
        if (part.toolInvocation.state === 'result') {
          parts.push({
            type: 'tool-result',
            payload: { toolCallId, toolName, result: part.toolInvocation.result },
          } as ChunkType);
        }
      }
    }
  }
  return parts;
}

/**
 * Run Agent's StructuredOutputProcessor once against the finished turn and collect the
 * chunks it would have streamed (object deltas and the final `object-result`).
 */
async function runStructuringPass({
  options,
  mastra,
  agentId,
  messageList,
  streamParts,
  requestContext,
  logger,
}: {
  options: StructuredOutputOptions<any>;
  mastra?: Mastra;
  agentId: string;
  messageList: MessageList;
  streamParts: ChunkType[];
  requestContext: RequestContext;
  logger: IMastraLogger;
}): Promise<ChunkType[]> {
  const chunks: ChunkType[] = [];
  try {
    const processor = new StructuredOutputProcessor({ ...options, logger });
    if (mastra) {
      processor.__registerMastra(mastra);
      if (options.useAgent) {
        try {
          processor.setAgent(mastra.getAgentById(agentId) as AnyAgent);
        } catch {
          // Fall back to the processor's internal structuring agent.
        }
      }
    }
    const state: Record<string, unknown> = { controller: { enqueue: (chunk: ChunkType) => chunks.push(chunk) } };
    await processor.processOutputStream({
      part: { type: 'finish' } as ChunkType,
      state,
      streamParts,
      messageList,
      requestContext,
      abort: (() => {
        throw new Error('abort is not supported in the durable structuring pass');
      }) as any,
      retryCount: 0,
    } as any);
    // Under errorStrategy 'strict' the processor records the failure and aborts in
    // processOutputStep (Agent retries there). The finish step cannot retry, so fail the run.
    processor.processOutputStep({
      state,
      messages: [],
      abort: ((reason: string, opts?: { metadata?: { error?: unknown } }) => {
        throw new StructuringPassError(reason, opts?.metadata?.error);
      }) as any,
    } as any);
  } catch (error) {
    if (error instanceof StructuringPassError || (options.errorStrategy ?? 'strict') === 'strict') throw error;
    logger.error('[DurableAgent] Structured output structuring pass failed', { error });
  }
  return chunks;
}

/**
 * Generate a durable thread title from messages belonging to that thread.
 * This is standalone so a remote worker can call it with the agent and memory
 * it rebuilt from its own Mastra instance.
 */
export async function generateDurableThreadTitle({
  agent,
  memory,
  threadId,
  resourceId,
  memoryConfig,
  messageListState,
  requestContext,
  tracingContext,
}: GenerateThreadTitleArgs & { agent: AnyAgent; memory: MastraMemory }): Promise<string | undefined> {
  const thread = await memory.getThreadById({ threadId });
  const mergedConfig = memory.getMergedThreadConfig(memoryConfig);
  const { shouldGenerate, model, instructions, minMessages } = agent.resolveTitleGenerationConfig(
    mergedConfig.generateTitle,
  );
  if (!shouldGenerate || thread?.title) return undefined;

  const titleMessageList = new MessageList().deserialize(messageListState);
  const uiMessages = agent.filterUiMessagesByThread(titleMessageList, threadId, titleMessageList.get.all.ui());
  if (uiMessages.length < (minMessages ?? 1)) return undefined;

  const userMessage = agent.getMostRecentUserMessage(uiMessages);
  if (!userMessage) return undefined;

  const title = await agent.genTitle(
    userMessage,
    requestContext ?? new RequestContext(),
    createObservabilityContext(tracingContext),
    model,
    instructions,
    uiMessages,
  );
  if (!title) return undefined;

  // genTitle is a model round trip, so another writer may have created the thread in the
  // meantime. Re-read before falling back to createThread, which upserts the whole row and
  // would drop metadata that writer stored.
  const currentThread = thread ?? (await memory.getThreadById({ threadId }));

  if (currentThread) {
    await memory.updateThread({
      id: threadId,
      title,
      metadata: currentThread.metadata ?? {},
      memoryConfig,
    });
  } else {
    await memory.createThread({
      threadId,
      resourceId,
      memoryConfig,
      title,
    });
  }
  return title;
}
